content:
:root {
  font-family: Inter, system-ui, Avenir, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  font-weight: 400;

  color-scheme: dark;
  color: rgba(255, 255, 255, 0.87);
  background-color: #121212;

  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  margin: 0;
  padding: 0;
  width: 100vw;
  height: 100vh;
  overflow: hidden;
  background-color: #0b0f19;
}

.app-container {
  position: relative;
  width: 100vw;
  height: 100vh;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.canvas-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
}

.title {
  position: absolute;
  top: 20px;
  left: 20px;
  z-index: 10;
  margin: 0;
  font-size: 1.5rem;
  font-weight: 700;
  background: linear-gradient(135deg, #60a5fa, #a78bfa, #f472b6);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.3);
  pointer-events: none;
}

.hint {
  position: absolute;
  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 10;
  margin: 0;
  font-size: 0.875rem;
  color: rgba(255, 255, 255, 0.6);
  background: rgba(0, 0, 0, 0.4);
  padding: 8px 16px;
  border-radius: 20px;
  backdrop-filter: blur(8px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  pointer-events: none;
  text-align: center;
}

.control-panel {
  position: absolute;
  top: 20px;
  right: 20px;
  z-index: 10;
  background: rgba(18, 24, 38, 0.85);
  backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 16px;
  padding: 20px;
  width: 280px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.control-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.control-group label {
  font-size: 0.8125rem;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.8);
  display: flex;
  justify-content: space-between;
}

.slider {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 6px;
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.15);
  outline: none;
  transition: background 0.2s;
}

.slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #60a5fa;
  cursor: pointer;
  box-shadow: 0 0 8px rgba(96, 165, 250, 0.6);
  transition: transform 0.1s, background 0.2s;
}

.slider::-webkit-slider-thumb:hover {
  transform: scale(1.2);
}

.select {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 8px;
  color: #fff;
  padding: 8px 12px;
  font-size: 0.875rem;
  outline: none;
  cursor: pointer;
  transition: border-color 0.2s;
}

.select option {
  background: #121826;
  color: #fff;
}

.select:hover, .select:focus {
  border-color: rgba(96, 165, 250, 0.6);
}

.btn {
  background: linear-gradient(135deg, #3b82f6, #6366f1);
  color: white;
  border: none;
  border-radius: 8px;
  padding: 10px 16px;
  font-size: 0.875rem;
  font-weight: 600;
  cursor: pointer;
  box-shadow: 0 4px 12px rgba(59, 130, 246, 0.4);
  transition: transform 0.1s, box-shadow 0.2s, background 0.2s;
}

.btn:hover {
  background: linear-gradient(135deg, #2563eb, #4f46e5);
  box-shadow: 0 6px 16px rgba(59, 130, 246, 0.6);
  transform: translateY(-1px);
}

.btn:active {
  transform: translateY(0);
}

@media (max-width: 600px) {
  .control-panel {
    top: auto;
    bottom: 60px;
    right: 10px;
    left: 10px;
    width: auto;
    max-height: 45vh;
    overflow-y: auto;
  }

  .title {
    font-size: 1.2rem;
    top: 15px;
    left: 15px;
  }
}

export interface ParticleSettings {
  particleCount: number;
  colorTheme: '霓虹' | '黄金' | 'サクラ' | 'サイバー';
  speed: number;
  particleSize: number;
  trailLength: number;
}

export interface ControlPanelProps {
  settings: ParticleSettings;
  onUpdateSettings: (settings: ParticleSettings) => void;
}

export interface ParticleCanvasProps {
  settings: ParticleSettings;
}

import { useEffect, useRef } from 'react';
import { ParticleCanvasProps } from '../types';

interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  size: number;
  color: string;
  angle: number;
  speed: number;
  life: number;
}

export default function ParticleCanvas({ settings }: ParticleCanvasProps) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationFrameId: number;
    let width = (canvas.width = window.innerWidth);
    let height = (canvas.height = window.innerHeight);

    const handleResize = () => {
      if (!canvas) return;
      width = canvas.width = window.innerWidth;
      height = canvas.height = window.innerHeight;
    };

    window.addEventListener('resize', handleResize);

    const mouse = {
      x: width / 2,
      y: height / 2,
      isMoving: false,
    };

    const handleMouseMove = (e: MouseEvent) => {
      mouse.x = e.clientX;
      mouse.y = e.clientY;
      mouse.isMoving = true;
    };

    const handleTouchMove = (e: TouchEvent) => {
      if (e.touches.length > 0) {
        mouse.x = e.touches[0].clientX;
        mouse.y = e.touches[0].clientY;
        mouse.isMoving = true;
      }
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('touchmove', handleTouchMove);

    // Color palettes
    const palettes = {
      '霓虹': ['#60a5fa', '#a78bfa', '#f472b6', '#34d399', '#fbbf24'],
      '黄金': ['#fbbf24', '#f59e0b', '#d97706', '#fffbeb', '#fef3c7'],
      'サクラ': ['#f472b6', '#fb7185', '#fda4af', '#fbcfe8', '#ffffff'],
      'サイバー': ['#38bdf8', '#818cf8', '#c084fc', '#22d3ee', '#f43f5e'],
    };

    const getColors = () => palettes[settings.colorTheme] || palettes['霓虹'];

    let particles: Particle[] = [];

    const initParticles = () => {
      particles = [];
      const colors = getColors();
      for (let i = 0; i < settings.particleCount; i++) {
        particles.push({
          x: Math.random() * width,
          y: Math.random() * height,
          vx: (Math.random() - 0.5) * 2,
          vy: (Math.random() - 0.5) * 2,
          size: Math.random() * settings.particleSize + 1,
          color: colors[Math.floor(Math.random() * colors.length)],
          angle: Math.random() * Math.PI * 2,
          speed: (Math.random() * 1.5 + 0.5) * settings.speed,
          life: Math.random() * 100,
        });
      }
    };

    initParticles();

    const render = () => {
      // Trail effect
      ctx.fillStyle = `rgba(11, 15, 25, ${settings.trailLength})`;
      ctx.fillRect(0, 0, width, height);

      const colors = getColors();

      // Adjust particle array length if settings change
      if (particles.length < settings.particleCount) {
        const diff = settings.particleCount - particles.length;
        for (let i = 0; i < diff; i++) {
          particles.push({
            x: Math.random() * width,
            y: Math.random() * height,
            vx: (Math.random() - 0.5) * 2,
            vy: (Math.random() - 0.5) * 2,
            size: Math.random() * settings.particleSize + 1,
            color: colors[Math.floor(Math.random() * colors.length)],
            angle: Math.random() * Math.PI * 2,
            speed: (Math.random() * 1.5 + 0.5) * settings.speed,
            life: Math.random() * 100,
          });
        }
      } else if (particles.length > settings.particleCount) {
        particles = particles.slice(0, settings.particleCount);
      }

      particles.forEach((p) => {
        // Move towards mouse
        const dx = mouse.x - p.x;
        const dy = mouse.y - p.y;
        const dist = Math.sqrt(dx * dx + dy * dy);

        if (dist > 1) {
          p.vx += (dx / dist) * 0.2 * settings.speed;
          p.vy += (dy / dist) * 0.2 * settings.speed;
        }

        // Damping
        p.vx *= 0.95;
        p.vy *= 0.95;

        p.x += p.vx * settings.speed;
        p.y += p.vy * settings.speed;

        // Boundaries
        if (p.x < 0) p.x = width;
        if (p.x > width) p.x = 0;
        if (p.y < 0) p.y = height;
        if (p.y > height) p.y = 0;

        // Draw particle
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.fillStyle = p.color;
        ctx.shadowBlur = 10;
        ctx.shadowColor = p.color;
        ctx.fill();
        ctx.shadowBlur = 0; // reset
      });

      animationFrameId = requestAnimationFrame(render);
    };

    render();

    return () => {
      window.removeEventListener('resize', handleResize);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('touchmove', handleTouchMove);
      cancelAnimationFrame(animationFrameId);
    };
  }, [settings]);

  return (
    <div className="canvas-container">
      <canvas ref={canvasRef} style={{ display: 'block' }} />
    </div>
  );
}

import { useState } from 'react';
import ParticleCanvas from './components/ParticleCanvas';
import ControlPanel from './components/ControlPanel';
import { ParticleSettings } from './types';

export default function App() {
  const [settings, setSettings] = useState<ParticleSettings>({
    particleCount: 300,
    colorTheme: '霓虹',
    speed: 1.0,
    particleSize: 3.0,
    trailLength: 0.2,
  });

  const handleUpdateSettings = (newSettings: ParticleSettings) => {
    setSettings(newSettings);
  };

  return (
    <div className="app-container">
      <h1 className="title">ParticleFlow</h1>
      <ParticleCanvas settings={settings} />
      <ControlPanel settings={settings} onUpdateSettings={handleUpdateSettings} />
      <p className="hint">画面上でマウスや指を動かすと、パーティクルが追いかけます</p>
    </div>
  );
}
